import fs from 'node:fs';import assert from 'node:assert/strict';import{createPublicClient,http}from'./enclave/node_modules/viem/_esm/index.js';import{LeaseReader}from'./enclave/network/lease-reader.mjs';import{prepareHostPolicy}from'./enclave/scripts/network/prepare-host-policy.mjs';
const p=JSON.parse(fs.readFileSync('outputs/windows-host-enrollment/transactions.json'));const owner='0x0b2d009c0c9af05b12100d77f3c815fea822ee61';const reader=new LeaseReader({rpc:['https://base-rpc.publicnode.com','https://base.drpc.org','https://mainnet.base.org'],addressBook:'0xab214342d5A490150A4A977063A2f88E21F80907'});const fresh=await prepareHostPolicy({policy:p.policy,owner,registry:p.observation.registry,reader});assert.equal(fresh.observation.ownershipCodeHash,p.observation.ownershipCodeHash);assert.equal(fresh.observation.pendingOwner,'0x'+'0'.repeat(40));assert.equal(fresh.observation.owner,owner);const tx=fresh.transactions.find(t=>t.purpose.startsWith('Owning wallet')).transaction;const c=createPublicClient({transport:http('https://base.drpc.org')});assert.equal(await c.getChainId(),8453);await c.call({account:owner,to:tx.to,data:tx.data,value:0n});const gas=await c.estimateGas({account:owner,to:tx.to,data:tx.data,value:0n});const out={status:'ready-for-owner-signature',checkedAt:new Date().toISOString(),purpose:'Commit the initial wallet policy for Enclave host nucbox-k11-4 only',transaction:tx,estimatedGas:String(gas),policyHash:fresh.policyHash,hostId:p.policy.hostId,observation:fresh.observation};fs.writeFileSync('outputs/windows-host-enrollment/policy-request.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify({status:out.status,gas:String(gas),hostId:out.hostId}));
